// Arquivo gerado a partir da auditoria SAMU 192 x Clinical Companion.
// Base: protocolos nacionais SAMU 192 / Ministério da Saúde + auditoria inicial do repositório clinical-companion.
// Observação: relatedPulsoProtocolSlug ficou null intencionalmente para o Lovable resolver contra o registry real de protocolos do app.

export type SamuProtocolLevel = "SBV" | "SAV";

export type SamuCoverageStatus =
  | "Encontrado"
  | "Parcial"
  | "Não localizado"
  | "Operacional SAMU"
  | "Sem título no sumário";

export type SamuContentStatus =
  | "Completo"
  | "Precisa revisar"
  | "Precisa criar"
  | "Não aplicável";

export type SamuPriority =
  | "Sala Vermelha"
  | "Emergência Clínica"
  | "Trauma"
  | "Pediatria"
  | "Obstetrícia"
  | "Procedimento"
  | "Operacional"
  | "Baixa prioridade";

export interface SamuProtocol {
  id: string;
  code: string;
  title: string;
  level: SamuProtocolLevel;
  category: string;
  coverageStatus: SamuCoverageStatus;
  contentStatus: SamuContentStatus;
  priority: SamuPriority;
  clinicalArea: string;
  relatedPulsoProtocolTitle: string | null;
  relatedPulsoProtocolSlug: string | null;
  source: string;
  sourceUrl: string;
  repoEvidenceUrl: string | null;
  tags: string[];
  notes: string | null;
  isOperational: boolean;
  needsMedicalReview: boolean;
}

